#include <cstdio>
#include <algorithm>

using namespace std;

int main() {
    int x;
    while(scanf("%d", &x), x) {
        if(x % 1111 == 0) {
            puts("NA");
        } else {
            int ans = 0;
            while(x != 6174) {
                // Create the largest and smallest numbers from digits
                int digits[4];
                for (int i = 0; i < 4; ++i) {
                    digits[i] = x % 10;
                    x /= 10;
                }
                sort(digits, digits + 4);
                // Compute the smallest and largest numbers
                int a = digits[0] * 1000 + digits[1] * 100 + digits[2] * 10 + digits[3]; // smallest
                int b = digits[3] * 1000 + digits[2] * 100 + digits[1] * 10 + digits[0]; // largest

                x = b - a;
                ans++;
            }
            printf("%d\n", ans);
        }
    }
}

